mapper.insert:
INSERT INTO customs_declaration (
    declaration_number, tracking_number, booking_id, status, declared_at,
    last_status_changed_at, destination_unlocode, projected_at
) VALUES (
    #{declarationNumber}, #{trackingNumber}, #{bookingId}, #{status}, #{declaredAt},
    #{lastStatusChangedAt}, #{destinationUnLocode}, #{projectedAt}
)
ON CONFLICT DO NOTHING

mapper.update:
UPDATE customs_declaration
   SET status = #{status},
       last_reason = #{reason},
       changed_by = #{changedBy},
       last_held_at = COALESCE(#{lastHeldAt}, last_held_at),
       last_status_changed_at = #{changedAt},
       projected_at = #{projectedAt}
 WHERE declaration_number = #{declarationNumber}
   AND last_status_changed_at <= #{changedAt}

mapper.select:
SELECT DISTINCT ON (tracking_number) declaration_number, tracking_number, booking_id, status, declared_at, last_status_changed_at, last_held_at, last_reason, changed_by, destination_unlocode, projected_at FROM customs_declaration WHERE tracking_number IN
#{number}
ORDER BY tracking_number, last_status_changed_at DESC, declared_at DESC

SELECT declaration_number, tracking_number, booking_id, status, declared_at,
       last_status_changed_at, last_held_at, last_reason,
       changed_by, destination_unlocode, projected_at
  FROM customs_declaration


        AND status <> 'CLEARED'


        AND tracking_number = #{trackingNumber}


        AND status = #{status}


 ORDER BY declared_at, declaration_number
 LIMIT #{limit}
